// Synthesized sound effects with the Web Audio API. No audio files are loaded;
// every sound is generated by oscillators and filtered noise.
export class SoundEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.engineOsc = null;
    this.engineGain = null;
    this.sirenTimer = null;
    this.sirenOn = false;
  }

  ensure() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.5;
    this.master.connect(this.ctx.destination);
  }

  setMuted(m) {
    this.muted = m;
    if (this.master) this.master.gain.value = m ? 0 : 0.5;
  }

  tone(freq, dur, type, vol, slideTo) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type || 'sine';
    o.frequency.setValueAtTime(freq, t);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t + dur);
    g.gain.setValueAtTime(vol || 0.2, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    o.connect(g); g.connect(this.master);
    o.start(t); o.stop(t + dur + 0.02);
  }

  noise(dur, vol, filterFreq) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const len = Math.max(1, Math.floor(this.ctx.sampleRate * dur));
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    const f = this.ctx.createBiquadFilter();
    f.type = 'lowpass'; f.frequency.value = filterFreq || 1200;
    const g = this.ctx.createGain();
    g.gain.value = vol || 0.3;
    src.connect(f); f.connect(g); g.connect(this.master);
    src.start(t);
  }

  shoot() { this.noise(0.16, 0.5, 2600); this.tone(180, 0.1, 'square', 0.18, 60); }
  punch() { this.noise(0.09, 0.3, 500); }
  pickup() { this.tone(660, 0.09, 'sine', 0.22); this.tone(990, 0.14, 'sine', 0.22); }
  cash() { this.tone(880, 0.1, 'triangle', 0.25); this.tone(1320, 0.18, 'triangle', 0.25); }
  horn() { this.tone(370, 0.35, 'square', 0.12); this.tone(466, 0.35, 'square', 0.1); }
  click() { this.tone(1200, 0.05, 'square', 0.12); }
  mission() {
    this.tone(523, 0.12, 'triangle', 0.25);
    setTimeout(() => this.tone(659, 0.12, 'triangle', 0.25), 120);
    setTimeout(() => this.tone(784, 0.22, 'triangle', 0.25), 240);
  }
  busted() { this.tone(220, 0.5, 'sawtooth', 0.25, 110); }

  // Continuous engine hum; call every frame with speed 0..1.
  engine(speed, driving) {
    if (!this.ctx) return;
    if (!driving || this.muted) {
      if (this.engineOsc) { try { this.engineOsc.stop(); } catch (e) { /* already stopped */ } this.engineOsc = null; }
      return;
    }
    if (!this.engineOsc) {
      this.engineOsc = this.ctx.createOscillator();
      this.engineOsc.type = 'sawtooth';
      this.engineGain = this.ctx.createGain();
      this.engineGain.gain.value = 0.05;
      const f = this.ctx.createBiquadFilter();
      f.type = 'lowpass'; f.frequency.value = 700;
      this.engineOsc.connect(f); f.connect(this.engineGain); this.engineGain.connect(this.master);
      this.engineOsc.start();
    }
    this.engineOsc.frequency.value = 55 + speed * 130;
    this.engineGain.gain.value = 0.03 + speed * 0.06;
  }

  // Two-tone police siren while wanted >= 2.
  siren(active) {
    if (!this.ctx) return;
    if (active && !this.sirenOn) {
      this.sirenOn = true;
      let high = false;
      this.sirenTimer = setInterval(() => {
        if (this.muted || !this.ctx) return;
        this.tone(high ? 950 : 700, 0.38, 'sine', 0.07);
        high = !high;
      }, 400);
    } else if (!active && this.sirenOn) {
      this.sirenOn = false;
      if (this.sirenTimer) clearInterval(this.sirenTimer);
      this.sirenTimer = null;
    }
  }
}
